	},
	bonds = {
		{ id = "the-lost-dwarves", name = "Les nains perdus", note = "Baelog a appris ce qu'il porte" },
		{ id = "grimlok", name = "Grimlok", note = "son chef" },
	},
})

Translate("frFR", "obsidian-sentinel", {
	title = "Sentinelle d'obsidienne",
	subtitle = "Gardien de verre noir",
	found = "Une caverne dans les profondeurs moyennes d'Uldaman",
	hint = [=[Cherchez le gardien de verre noir dans les cavernes d'Uldaman.]=],
	allegiance = "Les Créateurs",
	sections = {
		{
			title = "Résumé",
			text = [=[La Sentinelle d'obsidienne est l'un des gardiens de pierre d'{link:uldaman}Uldaman{/link}, mais elle est faite de verre sombre plutôt que de pierre. Les sorts qu'on lui lance sont souvent renvoyés sur ceux qui les jettent. Quand on la frappe, elle se fend. Chaque éclat tombe et devient un fragment qui combat de lui-même, et la sentinelle faiblit à mesure qu'elle se brise.]=],
		},
		{
			title = "Importance",
			text = [=[Le cœur de la sentinelle est une source d'énergie si puissante que les mages la convoitent. {link:tabetha}Tabetha{/link}, une mage qui vit seule dans le {link:dustwallow-marsh}Marécage d'Âprefange{/link}, a envoyé ceux en qui elle a confiance la prendre. Ses collègues la disaient folle de le demander.]=],
		},
		{ title = "Hauts faits", text = "• Elle garde une caverne d'{link:uldaman}Uldaman{/link}." },
	},
	chapters = {
		{
			title = "L'énergie d'Uldaman",
			hint = [=[Répondez à la mage d'Âprefange qui a besoin d'une source d'énergie.]=],
			text = [=[{link:tabetha}Tabetha{/link} avait besoin d'une source d'énergie, et les meilleures, disait-elle, étaient les plus anciennes et les plus difficiles à obtenir. Elle nomma la Sentinelle d'obsidienne. Quand on lui apporta sa source, elle fut ravie, et plus ravie encore que ses collègues sceptiques aient eu tort.]=],
		},
	},
	bonds = {
		{ id = "tabetha", name = "Tabetha", note = "a cherché son cœur" },
	},
})

Translate("frFR", "ancient-stone-keeper", {
	title = "Ancien gardien des pierres",
	subtitle = "Gardien de la salle du Temple",
	found = "La salle du Temple, dans les profondeurs d'Uldaman",
	hint = "Affrontez le vieux gardien de pierre de la salle du Temple.",
	allegiance = "Les Créateurs",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Ancien gardien des pierres est un gardien de pierre qui garde la salle du Temple dans les profondeurs inférieures d'{link:uldaman}Uldaman{/link}. Des gardiens et des intendants de pierre moindres servent dans les salles alentour, mais aucun n'est aussi vieux ni aussi fort. Quand des intrus entrent dans sa salle, il fait lever des tempêtes de sable qui tourbillonnent dans la chambre et décapent tout ce qu'elles touchent.]=],
		},
		{
			title = "Importance",
			text = [=[L'Ancien gardien des pierres est l'un des gardiens que les Créateurs laissèrent veiller sur la chambre forte tandis que ses maîtres dormaient. Il accomplit encore son œuvre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il garde la salle du Temple et invoque des tempêtes de sable contre les intrus.]=],
		},
	},
	bonds = {
		{ id = "archaedas", name = "Archaedas", note = "le plus grand gardien de la chambre forte" },
	},
})

Translate("frFR", "galgann-firehammer", {
	title = "Galgann Firehammer",
	subtitle = "Maître de la fouille Shadowforge",
	found = "L'excavation Shadowforge, dans les profondeurs d'Uldaman",
	hint = [=[Affrontez le Sombrefer qui mène les fouilleurs Shadowforge à Uldaman.]=],
	allegiance = "Nains Sombrefer · Shadowforge",
	aliases = { "Firehammer" },
	sections = {
		{
			title = "Résumé",
			text = [=[Galgann Firehammer commande la fouille Shadowforge à l'intérieur d'{link:uldaman}Uldaman{/link}. Il manie le feu. Il brûle ses ennemis de coups de fouet de flamme, les rend plus vulnérables au feu et embrase tout autour de lui d'un anneau de flammes. Ses géologues le gardent et font tomber leurs propres colonnes de feu. Quand on l'attaque, il jure par la barbe de {link:ruins-of-thaurissan}Thaurissan{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Galgann est la main des Shadowforge à {link:uldaman}Uldaman{/link}. Ses fouilleurs cherchent les pierres de puissance que le {link:gnomes}gnome{/link} {link:rigglefuzz}Rigglefuzz{/link} leur apprit à utiliser, et la magie qui pourrait donner une volonté à leurs golems. On dit que ce qu'ils veulent vraiment, ce sont les {link:lore-keeper-of-norgannon}Disques de Norgannon{/link}, pour le seigneur du feu qu'ils servent.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mène l'excavation sombrefer à l'intérieur d'{link:uldaman}Uldaman{/link}.
• Les siens gardent dans leurs barricades un rubis du collier brisé.]=],
		},
	},
	bonds = {
		{ id = "grimlok", name = "Grimlok", note = "son rival pour la chambre forte" },
	},
})

Translate("frFR", "grimlok", {
	title = "Grimlok",
	subtitle = "Chef des Stonevault",
	found = "La chambre de pierre, au fond d'Uldaman",
	hint = [=[Affrontez le chef trogg qui se dit roi dans les profondeurs d'Uldaman.]=],
	allegiance = "Troggs Stonevault",
	sections = {
		{
			title = "Résumé",
			text = [=[Grimlok est le chef des troggs Stonevault, le clan qui envahit {link:uldaman}Uldaman{/link} et en chassa les nains. C'est un chaman de la foudre, et un grand basilic à épines de jade combat à ses côtés. Quand il part au combat, il rugit qu'il est roi. Parmi ses trésors se trouve un saphir pris sur le collier d'un paladin mort.]=],
		},
		{
			title = "Importance",
			text = [=[Grimlok règne sur les troggs qui tiennent aujourd'hui {link:uldaman}Uldaman{/link}. Tant que son clan grouille dans ses salles, ni les nains ni les {link:dark-iron-dwarves}Sombrefer{/link} ne peuvent creuser en paix.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mène les Stonevault dans leur guerre contre les Shadowforge pour le contrôle de la chambre forte.
• Il a pris pour lui le saphir du collier brisé.]=],
		},
	},
	bonds = {
		{ id = "galgann-firehammer", name = "Galgann Firehammer", note = "son rival pour la chambre forte" },
		{ id = "revelosh", name = "Revelosh", note = "l'un des siens" },
	},
})

Translate("frFR", "remains-of-a-paladin", {
	title = "Restes d'un paladin",
	subtitle = "Un paladin tué à Uldaman",
	found = "La grande salle de temple près de l'entrée d'Uldaman",
	hint = [=[Cherchez les restes d'un chevalier humain dans les salles d'Uldaman.]=],
	allegiance = "Inconnue",
	aliases = { "le paladin tombé d'Uldaman" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dans un couloir de la grande salle de temple d'{link:uldaman}Uldaman{/link} reposent les restes d'un paladin humain. Il vint dans les {link:badlands}Terres ingrates{/link} pour une quête qu'il s'était lui-même choisie : purger une souillure maléfique qui, croyait-il, pesait sur le site de fouilles. Il portait un beau collier magique fait pour lui par Talvash del Kissel, un joaillier {link:gnomes}gnome{/link} d'{link:ironforge}Ironforge{/link}. Il mourut dans la chambre forte, et son collier fut brisé et ses gemmes dispersées. Son journal taché de sang, écrit dans la langue des humains, repose à côté de lui.]=],
		},
		{
			title = "Importance",
			text = [=[La mort du paladin projeta une longue ombre. Un rival de Talvash fit courir le bruit que le collier avait maudit son porteur, et le commerce du joaillier fut ruiné. Dans la {link:horde}Horde{/link}, les récupérateurs de Droffers et Fils entendirent aussi parler du collier, et le voulurent.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune archive ne donne le nom du paladin, son ordre ni sa patrie. Ce qu'était la souillure maléfique, et s'il la trouva, on ne le sait pas.]=],
		},
	},
	chapters = {
		{
			title = "Le journal du paladin",
			hint = "Cherchez le paladin mort dans les salles d'Uldaman.",
			text = [=[Le journal fut la dernière œuvre du paladin. Il avait découvert où chaque gemme était partie. Les nains Shadowforge avaient caché le rubis dans leurs barricades tandis qu'ils combattaient les troggs pour la chambre forte. Les troggs avaient mis la topaze dans une urne près d'un camp de nains d'{link:ironforge}Ironforge{/link}. Le chef des troggs avait pris le saphir. Du côté de la {link:horde}Horde{/link}, le journal ne put être lu que lorsque le troll {link:jarkal-mossmeld}Jarkal Mossmeld{/link} de {link:kargath}Kargath{/link} le traduisit, en échange de la possibilité d'étudier lui-même le collier.]=],
		},
	},
	mentions = {
		{ text = "Le collier brisé" },
		{ text = "Le savoir a un prix" },
		{ text = "La récupération du collier" },
		{ text = "Restaurer le collier" },
	},
	bonds = {
		{ id = "grimlok", name = "Grimlok", note = "a pris son saphir" },
		{ id = "galgann-firehammer", name = "Galgann Firehammer", note = "les siens ont pris son rubis" },
	},
})

Translate("frFR", "annora", {
	title = "Annora",
	subtitle = "Maître enchanteur",
	found = [=[Une grotte pleine de scorpides, à l'écart des salles d'Uldaman]=],
	hint = [=[Débarrassez la grotte des scorpides d'Uldaman, et voyez qui s'y cachait.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Annora est une enchanteresse humaine, maîtresse de son art, qui se cache dans une grotte d'{link:uldaman}Uldaman{/link} envahie de scorpides. Elle ne sort que lorsque les créatures ont disparu, et elle remercie ses sauveteurs avec émotion : elle commençait à craindre de devoir s'y cacher pour toujours. Elle partage son savoir-faire avec ceux qui l'ont mérité.]=],
		},
		{
			title = "Importance",
			text = [=[Annora est l'un des rares visages amis dans les profondeurs d'{link:uldaman}Uldaman{/link}. Qu'une maîtresse de son art se trouve cachée parmi les scorpides est l'un des récits les plus étranges de la chambre forte.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune archive ne dit qui est Annora, où elle apprit son art, ni ce qui l'amena à {link:uldaman}Uldaman{/link}.]=],
		},
	},
})
